 "content": "def transform(grid):
    """Recolor large solid rectangular patches to 4.

    Demos show rectangular patches at least 5x5; the test confirms the three
    qualifying patches present there. Smaller monochrome patches are left alone.
    """
    h = len(grid)
    w = len(grid[0]) if h else 0
    out = [row[:] for row in grid]
    marked = set()

    # For each top/bottom pair, find horizontal runs of columns whose cells
    # all match the top-row color throughout that vertical span.
    for top in range(h):
        for bottom in range(top + 4, h):
            same = [
                all(grid[r][c] == grid[top][c] for r in range(top, bottom + 1))
                for c in range(w)
            ]
            c = 0
            while c < w:
                if not same[c]:
                    c += 1
                    continue
                color = grid[top][c]
                end = c + 1
                while end < w and same[end] and grid[top][end] == color:
                    end += 1
                if end - c >= 5:
                    marked.update(
                        (r, col)
                        for r in range(top, bottom + 1)
                        for col in range(c, end)
