    # Detect any monochrome rectangle at least 4x5. Mark all cells covered by
    # such a rectangle, then use marked connected rectangles as the selected
    # patches. The demonstrations and solved test exhibit these patches.
    for top in range(h):
        for bottom in range(top + 3, h):
            common = [
                all(grid[r][c] == grid[top][c] for r in range(top, bottom + 1))
                for c in range(w)
            ]
            c = 0
            while c < w:
                if not common[c]:
                    c += 1
                    continue
                color = grid[top][c]
                end = c + 1
                while end < w and common[end] and grid[top][end] == color:
                    end += 1
                if end - c >= 5:
                    candidates.update(
                        (r, col)
                        for r in range(top, bottom + 1)
                        for col in range(c, end)
                    )
                c = end

    # Retain patches at least 4x5; this also captures patches whose component
    # is joined to a neighboring same-colored rectangular patch.
    for r, c in candidates:
        out[r][c] = 4
    return out
